const tape = require( 'tape' );
const dgttrf = require( '@stdlib/lapack/base/dgttrf/lib/main.js' );
const fs = require( 'fs' );
const path = require( 'path' );


tape( 'main export is a function', function test( t ) {
	t.equal( typeof dgttrf, 'function', 'main export is a function' );
	t.end();
} );

function arraysAlmostEqual( t, a, b, tol, msg ) {
	tol = tol === undefined ? 1e-10 : tol;
	msg = msg || '';
	const abs = require( '@stdlib/math/base/special/abs' );
	t.equal( a.length, b.length, msg + ' (length)' );
	for ( let i = 0; i < a.length; i++ ) {
		// Handle NaN comparison: treat NaN as equal to NaN for fixture robustness
		if ( Number.isNaN( a[i] ) && Number.isNaN( b[i] ) ) {
			t.ok( true, `${msg} (index ${i}): both NaN` );
		} else {
			t.ok( abs( a[i] - b[i] ) < tol, `${msg} (index ${i}): ${a[i]} vs ${b[i]}` );
		}
	}
}

const testCases = [
	{
		name: '3x3 positive values',
		dl: [ 2.0, 3.0 ],
		d: [ 4.0, 5.0, 6.0 ],
		du: [ 1.0, 2.0 ]
	},
	{
		name: '3x3 with zeros',
		dl: [ 0.0, 0.0 ],
		d: [ 1.0, 0.0, 1.0 ],
		du: [ 0.0, 0.0 ]
	},
	{
		name: '3x3 with negative values',
		dl: [ -1.0, -2.0 ],
		d: [ -3.0, 4.0, -5.0 ],
		du: [ -6.0, 7.0 ]
	},
	{
		name: '4x4 random values',
		dl: [ 0.5, -1.2, 3.3 ],
		d: [ 2.1, 0.0, -4.5, 5.5 ],
		du: [ 1.1, 2.2, -3.3 ]
	},
	{
		name: 'Singular matrix',
		dl: [ 1.0, 1.0 ],
		d: [ 0.0, 0.0, 0.0 ],
		du: [ 1.0, 1.0 ]
	},
	{
		name: '5x5 all ones',
		dl: [ 1, 1, 1, 1 ],
		d: [ 1, 1, 1, 1, 1 ],
		du: [ 1, 1, 1, 1 ]
	},
	{
		name: '5x5 alternating sign',
		dl: [ 1, -1, 1, -1 ],
		d: [ -1, 1, -1, 1, -1 ],
		du: [ -1, 1, -1, 1 ]
	},
	{
		name: '5x5 very large values',
		dl: [ 1e10, 1e10, 1e10, 1e10 ],
		d: [ 1e10, 1e10, 1e10, 1e10, 1e10 ],
		du: [ 1e10, 1e10, 1e10, 1e10 ]
	},
	{
		name: '5x5 very small values',
		dl: [ 1e-10, 1e-10, 1e-10, 1e-10 ],
		d: [ 1e-10, 1e-10, 1e-10, 1e-10, 1e-10 ],
		du: [ 1e-10, 1e-10, 1e-10, 1e-10 ]
	},
	{
		name: '5x5 repeated values',
		dl: [ 2, 2, 2, 2 ],
		d: [ 3, 3, 3, 3, 3 ],
		du: [ 4, 4, 4, 4 ]
	},
	{
		name: '5x5 nearly singular',
		dl: [ 1e-12, 1e-12, 1e-12, 1e-12 ],
		d: [ 1e-12, 1e-12, 1e-12, 1e-12, 1e-12 ],
		du: [ 1e-12, 1e-12, 1e-12, 1e-12 ]
	}
];

testCases.forEach( function runTest( testCase ) {
	tape( `dgttrf: JS vs Python LAPACK: ${testCase.name}`, function dgttrfTest( t ) {
		// Read fixture
		var fixtureName = testCase.name.replace( /\s+/g, '_' ).toLowerCase() + '.json';
		var fixturePath = path.join( __dirname, 'fixtures', fixtureName );
		var pyOut;
		try {
			pyOut = JSON.parse( fs.readFileSync( fixturePath, 'utf8' ) );
		} catch ( err ) {
			t.fail( `Missing or invalid fixture: ${fixturePath}` );
			t.end();
			return;
		}
		var jsOut;
		var jsError;
		try {
			jsOut = dgttrf( [].concat( testCase.dl ), [].concat( testCase.d ), [].concat( testCase.du ) );
		} catch ( err ) {
			jsError = err;
		}
		// Remove flag functionality: always print on failure only
		var failedPin = null;
		try {
			t.notOk( jsError, `JS should not throw: ${jsError && jsError.message}` );
			try { arraysAlmostEqual( t, jsOut.dl, pyOut.dl, 1e-10, 'dl' ); } catch ( e ) { failedPin = 'dl'; throw e; }
			try { arraysAlmostEqual( t, jsOut.d, pyOut.d, 1e-10, 'd' ); } catch ( e ) { failedPin = 'd'; throw e; }
			try { arraysAlmostEqual( t, jsOut.du, pyOut.du, 1e-10, 'du' ); } catch ( e ) { failedPin = 'du'; throw e; }
			try { arraysAlmostEqual( t, jsOut.du2, pyOut.du2, 1e-10, 'du2' ); } catch ( e ) { failedPin = 'du2'; throw e; }
			try {
				// Replace Array.from for compatibility:
				var jsIpiv = [];
				for ( var i = 0; i < jsOut.ipiv.length; i++ ) {
					jsIpiv.push( jsOut.ipiv[ i ] );
				}
				var pyIpiv0 = [];
				for ( var j = 0; j < pyOut.ipiv.length; j++ ) {
					pyIpiv0.push( pyOut.ipiv[ j ] - 1 );
				}
				t.deepEqual( jsIpiv, pyIpiv0, 'ipiv' );
			} catch ( e ) { failedPin = 'ipiv'; throw e; }
			try {
				t.equal( jsOut.info === undefined ? 0 : jsOut.info, pyOut.info, 'info' );
			} catch ( e ) { failedPin = 'info'; throw e; }
		} catch ( e ) {
			console.log( `\n[DEBUG FAIL] Test case: ${testCase.name}` );
			if ( failedPin ) {
				console.log( `Failed at pin: ${failedPin}` );
				if ( !jsError ) {
					console.log( 'Python:', JSON.stringify( pyOut[ failedPin ], null, 2 ) );
					console.log( 'JS:', JSON.stringify( jsOut[ failedPin ], null, 2 ) );
				}
			} else {
				console.log( 'General failure:', e.message );
			}
			t.fail( e.message );
		}
		t.end();
	} );
} );
